// src/app/call/page.jsx
"use client";

import React, { useEffect, useRef, useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";

const STUN_CONFIG = {
  iceServers: [{ urls: "stun:stun.l.google.com:19302" }],
};

export default function CallPage() {
  const { user, loading } = useAuth();
  const socket = useSocket();

  // call state
  const [callData, setCallData] = useState(null);
  const [inCall, setInCall] = useState(false);
  const [calling, setCalling] = useState(false);

  // refs
  const localRef = useRef(null);
  const remoteRef = useRef(null);
  const pcRef = useRef(null);
  const pendingICE = useRef([]);

  // 1) Join your socket room
  useEffect(() => {
    if (!socket || !user) return;
    socket.emit("join", user.id);
  }, [socket, user]);

  // 2) Signaling listeners (exactly like in your chat page)
  useEffect(() => {
    if (!socket) return;

    // Incoming call
    const onIncoming = ({ from, offer, isVoice }) => {
      setCallData({ from, incoming: true, offer, isVoice });
    };
    socket.on("incoming_call", onIncoming);

    // Callee accepts our outgoing call
    const onAccepted = async ({ answer }) => {
      const pc = pcRef.current;
      if (!pc) return;
      await pc.setRemoteDescription(answer);
      setInCall(true);
    };
    socket.on("call_accepted", onAccepted);

    // ICE candidates
    const onIce = ({ candidate }) => {
      const pc = pcRef.current;
      if (pc && pc.remoteDescription) {
        pc.addIceCandidate(candidate).catch(console.error);
      } else {
        pendingICE.current.push(candidate);
      }
    };
    socket.on("ice_candidate", onIce);

    // Hang-up
    socket.on("call_ended", () => {
      hangUp();
    });

    return () => {
      socket.off("incoming_call", onIncoming);
      socket.off("call_accepted", onAccepted);
      socket.off("ice_candidate", onIce);
      socket.off("call_ended", hangUp);
    };
  }, [socket]);

  // 3) Kick off outgoing call when `callData` is set with `{ to, incoming:false }`
  useEffect(() => {
    if (!callData || !socket) return;
    const { incoming, to, from, offer, isVoice } = callData;

    (async () => {
      // 3a) Grab media
      let stream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: !isVoice,
          audio: true,
        });
      } catch {
        alert("Camera/microphone access denied");
        setCallData(null);
        return;
      }
      localRef.current.srcObject = stream;

      // 3b) Create PeerConnection
      const pc = new RTCPeerConnection(STUN_CONFIG);
      pcRef.current = pc;
      pendingICE.current.forEach((c) =>
        pc.addIceCandidate(c).catch(console.error)
      );
      pendingICE.current = [];

      stream.getTracks().forEach((t) => pc.addTrack(t, stream));
      pc.ontrack = (e) => (remoteRef.current.srcObject = e.streams[0]);
      pc.onicecandidate = ({ candidate }) => {
        if (candidate) {
          socket.emit("ice_candidate", {
            to: incoming ? from : to,
            candidate,
          });
        }
      };

      // 3c) Offer or answer
      if (incoming) {
        await pc.setRemoteDescription(offer);
        const ans = await pc.createAnswer();
        await pc.setLocalDescription(ans);
        socket.emit("answer_call", { to: from, answer: ans });
        setInCall(true);
      } else {
        const off = await pc.createOffer();
        await pc.setLocalDescription(off);
        socket.emit("call_user", { to, offer: off, isVoice });
      }
      setCalling(true);
    })();
  }, [callData, socket]);

  // 4) Hang-up helper
  const hangUp = () => {
    const pc = pcRef.current;
    if (pc) pc.close();
    [localRef, remoteRef].forEach((r) => {
      if (r.current?.srcObject) {
        r.current.srcObject.getTracks().forEach((t) => t.stop());
        r.current.srcObject = null;
      }
    });
    if (callData) {
      const peer = callData.incoming ? callData.from : callData.to;
      socket.emit("end_call", { to: peer });
    }
    setCallData(null);
    setCalling(false);
    setInCall(false);
    pendingICE.current = [];
  };

  if (loading || !socket) return <p className="text-white">Loading…</p>;

  return (
    <div className="p-6 text-white">
      <h1 className="text-2xl font-bold mb-4">Start a Call</h1>

      {/* List of online users, same as before */}
      <ul className="space-y-3">
        {/** Replace `onlineUsers` with the IDs you get from your Context or an API */}
        {["userA", "userB", "userC"].map((id) => (
          <li key={id} className="flex justify-between items-center">
            <span>{id}</span>
            <div className="space-x-2">
              <button
                onClick={() =>
                  setCallData({ to: id, incoming: false, isVoice: false })
                }
                className="bg-green-500 px-3 py-1 rounded"
              >
                🎥
              </button>
              <button
                onClick={() =>
                  setCallData({ to: id, incoming: false, isVoice: true })
                }
                className="bg-blue-500 px-3 py-1 rounded"
              >
                🎤
              </button>
            </div>
          </li>
        ))}
      </ul>

      {/* In-call UI */}
      {(calling || inCall) && (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50">
          <div className="bg-gray-800 p-4 rounded-lg flex flex-col items-center">
            <video
              ref={remoteRef}
              autoPlay
              playsInline
              className="w-80 h-60 mb-4"
            />
            <video
              ref={localRef}
              autoPlay
              playsInline
              muted
              className="w-32 h-24 rounded-lg border-2 border-white"
            />
            <button
              onClick={hangUp}
              className="mt-4 bg-red-600 px-4 py-2 rounded"
            >
              End Call
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
